// Обучение — по образцу «Симулятора Летки»: короткие уроки за самолёт и за ПВО. Проиграть нельзя (самолёт неуязвим,
// подвеска пополняется). На каждом шаге — подсказка; кнопка «?» ставит игру на паузу и объясняет комплекс или оружие.
// Урок сам запускает режим air.js или defense.js со своими опциями и следит за шагами через tick(T).
/* global THREE */
import { SAM, AG, SAM_TYPE, AG_KIND, THREAT, SAM_COST, HELI_LOADOUTS } from './arsenal.js?v=20261024u';
import { samKnown } from './sim/combined.js?v=20261024u';
import { spotNear, freeGround } from './mission.js?v=20261024u';
import { riverX } from './city.js?v=20261024u';
import { iconize } from './icons.js?v=20261024u';
import { tr } from './i18n.js?v=20261024u';

const K = (k) => `<kbd>${k}</kbd>`;
// подписи управления: ПК или телефон
const ctl = (C, pc, phone) => (C.IS_TOUCH ? phone : pc);
// сторона: pv — комплекс стороны ПВО (setup.side), av — оружие игрока-лётчика (другая сторона); пары — по паритету
const pv = (C, east, west) => (C.setup.side === 'east' ? east : west), av = (C, east, west) => (C.setup.side === 'east' ? west : east);
const objOf = (C, key) => (C.S ? C.S.objects : C.city.objects).find((o) => o.key === key); // до старта боя (урок из меню — боя на фоне нет) — объекты города: те же места
// «АВТО» в уроке: показ — включено, «Теперь вы» — выключено (иначе практику делает помощник); выбор игрока вернётся после урока
function autoSet(C, T, on) { if (T.d.auto0 === undefined) T.d.auto0 = C.auto; C.auto = on; for (const id of ['tAuto', 'opAuto']) { const b = document.getElementById(id); if (b) b.classList.toggle('on', on); } }

// ветки обучения: обычная игра и «Мульти-волна»
export const TSIDES = { air: tr('за самолёт'), def: tr('за ПВО'), heli: tr('за вертолёт'), matk: tr('мульти-волна за волну'), mdef: tr('мульти-волна за ПВО') };
// «Мульти-волна»: состояние режима, стоимость плана, цели наряда, готовый наряд урока
const DS = (C) => C.ctrl.inner.st;
const cost = (D) => Object.entries(D.plan.n).reduce((s, [k, n]) => s + (THREAT[k] ?? 3) * n, 0);
function oKeys(C) { const D = DS(C), I = C.ctrl.inner, ks = new Set(); for (const [k, n] of Object.entries(D.plan.n)) for (let i = 0; i < n; i++) { const t = I.tkeyOf(k, i); if (t) ks.add(t); } return ks; }
function give(st, k, n, o, extra = () => ({})) { const c = st.plan.cfg[k] = st.plan.cfg[k] || { pts: [], alt: null, t: null, sam: false, tgt: null, units: [] }, i0 = st.plan.n[k] || 0; st.plan.n[k] = i0 + n; for (let i = 0; i < n; i++) c.units[i0 + i] = { sam: false, tgt: o.id, ...extra(i) }; }

// ═════════════ Карточки «?» ═════════════
